function getTitle(user) {
  const totalMoney = user.cash + user.bank;
  if (user.stars >= 4) return "🏴‍☠️ Kingpin / Mafia Underworld";
  if (user.stars >= 2) return "🥷 Penjenayah Dikehendaki";
  if (totalMoney >= 1000000) return "👑 CEO Korporat / Jutawan";
  if (totalMoney >= 200000) return "💼 Pengurus Eksekutif";
  if (totalMoney >= 50000) return "⭐ Pekerja Teladan";
  return "🌱 Pekerja Am / Orang Awam";
}

async function checkAndAwardBadges(user, sock, from, cleanSender) {
  const newBadges = [];
  const totalMoney = user.cash + user.bank;
  const userPhone = cleanSender.split("@")[0];

  if (user.stats.works >= 5 && !user.badges.includes("🔨 Buruh Gigih")) {
    user.badges.push("🔨 Buruh Gigih");
    newBadges.push("🔨 Buruh Gigih");
  }
  if (user.stats.works >= 25 && !user.badges.includes("🏆 Raja Halal")) {
    user.badges.push("🏆 Raja Halal");
    newBadges.push("🏆 Raja Halal");
  }
  if (user.stats.crimes >= 5 && !user.badges.includes("🕶️ Buronan Jalanan")) {
    user.badges.push("🕶️ Buronan Jalanan");
    newBadges.push("🕶️ Buronan Jalanan");
  }
  if (user.stats.crimes >= 20 && !user.badges.includes("💀 Legend Underworld")) {
    user.badges.push("💀 Legend Underworld");
    newBadges.push("💀 Legend Underworld");
  }
  if (totalMoney >= 100000 && !user.badges.includes("💰 Bangsawan Cyber")) {
    user.badges.push("💰 Bangsawan Cyber");
    newBadges.push("💰 Bangsawan Cyber");
  }
  if (user.vehicles.length >= 3 && !user.badges.includes("🏎️ Kaki Koleksi")) {
    user.badges.push("🏎️ Kaki Koleksi");
    newBadges.push("🏎️ Kaki Koleksi");
  }
  if ((user.stats.racesWon || 0) >= 5 && !user.badges.includes("⚡ Raja Rempit")) {
    user.badges.push("⚡ Raja Rempit");
    newBadges.push("⚡ Raja Rempit");
  }

  for (const bName of newBadges) {
    try {
      const imgBuffer = await generateBadge(bName, userPhone);
      await sock.sendMessage(from, {
        image: imgBuffer,
        caption: `╭━━━ 🎖️ *PENSIJILAN LENCANA RASMI* ━━━\n┃ 👤 Pemilik: @${userPhone}\n┃ 🏅 Lencana: *${bName}*\n┃ 🏛️ Pengeluar: *Airi's Corner Grid*\n╰━━━━━━━━━━━━━━━━━━━━━━━━━━━━`,
        mentions: [cleanSender]
      });
    } catch (err) {
      console.log("Ralat menjana imej badge:", err);
    }
  }
  return newBadges;
}

// --- 9. ENGINE UTAMA ---
async function startBotEngine() {
  const { state, saveCreds } = await useMultiFileAuthState("auth_session");
  
  const sock = makeWASocket({
    auth: state,
    logger: pino({ level: "silent" }),
    browser: Browsers.macOS("Desktop"),
    printQRInTerminal: false
  });

  sock.ev.on("creds.update", saveCreds);

  sock.ev.on("connection.update", (update) => {
    const { connection, lastDisconnect, qr } = update;
    if (qr) { currentQR = qr; isConnected = false; }
    if (connection === "close") {
      isConnected = false;
      if (lastDisconnect?.error?.output?.statusCode !== 401) startBotEngine();
    } else if (connection === "open") {
      isConnected = true;
      currentQR = "";
      console.log("✅ AIRI'S CORNER BOT BERJAYA BERSAMBUNG KE WHATSAPP!");
    }
  });

  sock.ev.on("group-participants.update", async (anu) => {
    try {
      const { id, participants, action } = anu;
      if (action === "add") {
        for (const num of participants) {
          const cleanId = num.replace(/[^0-9]/g, "") + "@s.whatsapp.net";
          getUser(cleanId);
          await sock.sendMessage(id, { text: `🎉 Selamat datang @${num.split("@")[0]} ke Airi's Corner! Starter pack RM500 sedia. Taip \`.menu\` untuk mula.`, mentions: [num] });
        }
      }
    } catch (err) { console.log(err); }
  });

  sock.ev.on("messages.upsert", async ({ messages }) => {
    const m = messages[0];
    if (!m.message) return;
    const from = m.key.remoteJid;
    if (from.endsWith("@g.us")) {
      const db = loadDB();
      if (!db.groups) db.groups = [];
      if (!db.groups.includes(from)) { db.groups.push(from); saveDB(db); }
    }
  });

  // Auto report 12 malam
  let lastResetDate = new Date().getDate();
  setInterval(async () => {
    const now = new Date();
    if (now.getHours() === 0 && now.getDate() !== lastResetDate) {
      lastResetDate = now.getDate();
      const db = loadDB();
      const usersArr = Object.entries(db.users || {}).map(([id, data]) => ({
        id, works: data.stats?.works || 0, crimes: data.stats?.crimes || 0, cash: (data.cash || 0) + (data.bank || 0)
      }));
      if (usersArr.length > 0) {
        const topWorker = [...usersArr].sort((a, b) => b.works - a.works)[0];
        const topCriminal = [...usersArr].sort((a, b) => b.crimes - a.crimes)[0];
        const topRich = [...usersArr].sort((a, b) => b.cash - a.cash)[0];
        const reportUI = `╭━━━ 🌙 *LAPORAN TENGAH MALAM* 🌙 ━━━\n┃ 🏆 Raja Kerja: @${topWorker.id.split("@")[0]} (${topWorker.works} shift)\n┃ 🏴‍_️ Penjenayah: @${topCriminal.id.split("@")[0]} (${topCriminal.crimes} misi)\n┃ 💰 Jutawan: @${topRich.id.split("@")[0]} (RM ${topRich.cash.toLocaleString()})\n╰━━━━━━━━━━━━━━━━━━━━━━━━━━━━━`;
        for (const gId of (db.groups || [])) {
          await sock.sendMessage(gId, { text: reportUI, mentions: [topWorker.id, topCriminal.id, topRich.id].filter(Boolean) }).catch(() => {});
        }
      }
      for (let id in db.users) { db.users[id].stats = { works: 0, crimes: 0, bails: 0, racesWon: db.users[id].stats?.racesWon || 0 }; }
      saveDB(db);
    }
  }, 60 * 1000);

  // --- 10. MESEJ & ARAHAN BOT ---
  sock.ev.on("messages.upsert", async ({ messages }) => {
    const m = messages[0];
    if (!m.message) return;
    const from = m.key.remoteJid;
    const msgType = Object.keys(m.message)[0];
    const text = (msgType === "conversation") ? m.message.conversation :
                 (msgType === "extendedTextMessage") ? m.message.extendedTextMessage.text : "";

    if (!text.startsWith(".")) return;
    const args = text.slice(1).trim().split(/ +/);
    const cmd = args.shift().toLowerCase();
    const sender = m.key.participant || from;
    const cleanSender = sender.replace(/[^0-9]/g, "") + "@s.whatsapp.net";
    const user = getUser(cleanSender);
    const now = Date.now();

    if (now < user.cooldowns.jailUntil && cmd !== "upah_lawyer" && cmd !== "myid") {
      const remMin = Math.ceil((user.cooldowns.jailUntil - now) / 60000);
      return sock.sendMessage(from, { text: `🚨 Dalam lokap polis! Baki: *${remMin} minit*. Taip \`.upah_lawyer\` (RM500) untuk bebas.`, mentions: [cleanSender] });
    }

    if (cmd === "menu" || cmd === "help") {
      return sock.sendMessage(from, { text: `╭━━━ 🖥️ *AIRI'S CORNER OS* ━━━\n┃ 💼 .list_kerja - Senarai 50 kerja\n┃ .pilih_kerja [id] - Tukar jawatan\n┃ .kerja - Bekerja & terima gaji\n┃ .daily - Gaji harian percuma\n┃ .showroom & .beli_kenderaan\n┃ .shop & .makan\n┃ .deposit / .withdraw / .transfer\n┃ .rompak @user\n┃ .jenayah_menu & .buat_jenayah\n┃ .myid & .profile & .badges\n┃ .top & .upah_lawyer\n╰━━━━━━━━━━━━━━━━━━━━━━━━━━━━━` });
    }

    if (cmd === "daily") {
      if (now < user.cooldowns.daily) {
        const remHours = Math.ceil((user.cooldowns.daily - now) / 3600000);
        return sock.sendMessage(from, { text: `⏳ Tunggu *${remHours} jam* lagi untuk tuntutan seterusnya.`, mentions: [cleanSender] });
      }
      user.cash += 250;
      user.cooldowns.daily = now + (24 * 60 * 60 * 1000);
      updateUser(cleanSender, user);
      return sock.sendMessage(from, { text: `🎁 Bantuan harian +RM 250 masuk akaun!`, mentions: [cleanSender] });
    }

    if (cmd === "myid" || cmd === "ic") {
      const title = getTitle(user);
      const activeJob = JOBS.find(j => j.id === user.jobId)?.name || "Pekerja Am";
      return sock.sendMessage(from, { text: `╭━━━ 🪪 *CYBER ID* ━━━\n┃ User: @${cleanSender.split("@")[0]}\n┃ Pangkat: ${title}\n┃ Jawatan: ${activeJob}\n┃ Tunai: RM ${user.cash.toLocaleString()}\n┃ Bank: RM ${user.bank.toLocaleString()}\n┃ Wanted: ${"⭐".repeat(user.stars) || "0"}\n╰━━━━━━━━━━━━━━━━━━`, mentions: [cleanSender] });
    }

    // --- SISTEM KERJA (50 PILIHAN) ---
    if (cmd === "list_kerja" || cmd === "jobs") {
      let jobList = `╭━━━ 💼 *SENARAI 50 KERJA HALAL* ━━━\n`;
      JOBS.forEach(j => {
        jobList += `• *[ID ${j.id}]* ${j.name} ➔ RM ${j.pay}\n`;
      });
      jobList += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nTaip \`.pilih_kerja [id]\` untuk tetapkan jawatan anda!`;
      return sock.sendMessage(from, { text: jobList });
    }

    if (cmd === "pilih_kerja" || cmd === "setjob") {
      const jId = parseInt(args[0]);
      const targetJob = JOBS.find(j => j.id === jId);
      if (!targetJob) return sock.sendMessage(from, { text: `❌ ID kerja tidak sah! Sila semak \`.list_kerja\` (ID 1 hingga 50).` });

      user.jobId = targetJob.id;
      updateUser(cleanSender, user);
      return sock.sendMessage(from, { text: `🏢 Berjaya! Anda kini berkhidmat sebagai *${targetJob.name}* (Gaji: RM ${targetJob.pay} / shift).\nTaip \`.kerja\` untuk mula bertugas!`, mentions: [cleanSender] });
    }

    if (cmd === "kerja" || cmd === "work") {
      const currentJob = JOBS.find(j => j.id === user.jobId) || JOBS[0];
      const cd = 3 * 60 * 1000;
      if (now < user.cooldowns.work) {
        const rem = Math.ceil((user.cooldowns.work - now) / 1000);
        return sock.sendMessage(from, { text: `⚠️ Rehat dulu, tunggu *${rem} saat* lagi. (Tip: Guna \`.makan\` untuk reset masa).`, mentions: [cleanSender] });
      }

      user.cash += currentJob.pay;
      user.stats.works += 1;
      user.cooldowns.work = now + cd;

      await checkAndAwardBadges(user, sock, from, cleanSender);
      updateUser(cleanSender, user);

      const dialog = DIALOG_KERJA[Math.floor(Math.random() * DIALOG_KERJA.length)];
      return sock.sendMessage(from, { text: `╭━━━ 💼 *SLIP GAJI* ━━━\n┃ Jawatan: ${currentJob.name} [ID ${currentJob.id}]\n┃ Payout: +RM ${currentJob.pay.toLocaleString()}\n┃\n┃ _"${dialog}"_\n╰━━━━━━━━━━━━━━━━━`, mentions: [cleanSender] });
    }

    // --- BANK, SHOP, SHOWROOM, JENAYAH, PVP ---
    if (cmd === "deposit" || cmd === "dep") {
      const amt = args[0] === "all" ? user.cash : parseInt(args[0]);
      if (isNaN(amt) || amt <= 0 || user.cash < amt) return sock.sendMessage(from, { text: `❌ Jumlah deposit tidak sah atau tunai kurang.` });
      user.cash -= amt; user.bank += amt;
      updateUser(cleanSender, user);
      return sock.sendMessage(from, { text: `🏦 Berjaya simpan RM ${amt.toLocaleString()} ke dalam bank.` });
    }

    if (cmd === "withdraw" || cmd === "wd") {
      const amt = args[0] === "all" ? user.bank : parseInt(args[0]);
      if (isNaN(amt) || amt <= 0 || user.bank < amt) return sock.sendMessage(from, { text: `❌ Jumlah pengeluaran tidak sah atau baki bank kurang.` });
      user.bank -= amt; user.cash += amt;
      updateUser(cleanSender, user);
      return sock.sendMessage(from, { text: `💵 Berjaya keluarkan RM ${amt.toLocaleString()} tunai.` });
    }

    if (cmd === "transfer" || cmd === "pay") {
      const targetTag = m.message.extendedTextMessage?.contextInfo?.mentionedJid?.[0];
      const amt = parseInt(args[1]);
      if (!targetTag || isNaN(amt) || amt <= 0 || user.cash < amt) return sock.sendMessage(from, { text: `❌ Format: \`.transfer @user [jumlah]\`` });
      const cleanTarget = targetTag.replace(/[^0-9]/g, "") + "@s.whatsapp.net";
      const targetUser = getUser(cleanTarget);
      user.cash -= amt; targetUser.cash += amt;
      updateUser(cleanSender, user); updateUser(cleanTarget, targetUser);
      return sock.sendMessage(from, { text: `💸 Berjaya transfer RM ${amt.toLocaleString()} kepada @${cleanTarget.split("@")[0]}!`, mentions: [cleanSender, cleanTarget] });
    }

    if (cmd === "showroom") {
      let ui = `╭━━━ 🏎️ *SHOWROOM KENDERAAN* ━━━\n`;
      VEHICLES.slice(0, 15).forEach(v => { ui += `• *[${v.id}]* ${v.name} - RM ${v.price.toLocaleString()}\n`; });
      ui += `*(Taip .showroom2 untuk senarai seterusnya)*\nTaip \`.beli_kenderaan [id]\``;
      return sock.sendMessage(from, { text: ui });
    }

    if (cmd === "beli_kenderaan") {
      const v = VEHICLES.find(item => item.id === args[0]);
      if (!v || user.cash < v.price) return sock.sendMessage(from, { text: `❌ Kenderaan tidak dijumpai atau duit tak cukup.` });
      user.cash -= v.price; user.vehicles.push(v.id);
      await checkAndAwardBadges(user, sock, from, cleanSender);
      updateUser(cleanSender, user);
      return sock.sendMessage(from, { text: `🎉 Tahniah! Anda kini pemilik sah *${v.name}*.`, mentions: [cleanSender] });
    }

    if (cmd === "profile" || cmd === "garaj") {
      return sock.sendMessage(from, { text: `╭━━━ 🎒 *PROFIL ANDA* ━━━\n┃ Garaj: ${user.vehicles.join(", ") || "Tiada"}\n┃ Inventori: ${user.inventory.map(i => i.name).join(", ") || "Kosong"}\n┃ Makanan: ${user.food.join(", ") || "Kosong"}\n╰━━━━━━━━━━━━━━━━━━`, mentions: [cleanSender] });
    }

    if (cmd === "shop" || cmd === "warung") {
      let s = `╭━━━ 🍔 *WARUNG MAKANAN* ━━━\n`;
      FOOD_ITEMS.forEach(f => { s += `• *[${f.id}]* ${f.name} - RM ${f.price} (${f.desc})\n`; });
      return sock.sendMessage(from, { text: s + `\nTaip \`.beli_makanan [id]\` & \`.makan [id]\`` });
    }

    if (cmd === "beli_makanan") {
      const f = FOOD_ITEMS.find(item => item.id === args[0]);
      if (!f || user.cash < f.price) return sock.sendMessage(from, { text: `❌ Tidak cukup duit atau makanan tiada.` });
      user.cash -= f.price; user.food.push(f.id);
      updateUser(cleanSender, user);
      return sock.sendMessage(from, { text: `🍽️ Berjaya beli ${f.name}!` });
    }

    if (cmd === "makan") {
      const idx = user.food.indexOf(args[0]);
      if (idx === -1) return sock.sendMessage(from, { text: `❌ Tiada makanan tersebut dalam beg.` });
      user.food.splice(idx, 1);
      if (args[0] === "nasilemak") user.cooldowns.work = 0;
      updateUser(cleanSender, user);
      return sock.sendMessage(from, { text: `😋 Nyum! Tenaga dipulihkan & cooldown kerja diset semula!` });
    }

    if (cmd === "blackmarket" || cmd === "bm") {
      let bm = `╭━━━ 🏴‍☠️ *BLACK MARKET* ━━━\n`;
      BLACKMARKET_ITEMS.forEach(i => { bm += `• *[${i.id}]* ${i.name} - RM ${i.price.toLocaleString()}\n`; });
      return sock.sendMessage(from, { text: bm + `\nTaip \`.beli_device [id]\`` });
    }

    if (cmd === "beli_device") {
      const item = BLACKMARKET_ITEMS.find(i => i.id === args[0]);
      if (!item || user.cash < item.price) return sock.sendMessage(from, { text: `❌ Gagal beli gajet.` });
      user.cash -= item.price; user.inventory.push({ id: item.id, name: item.name });
      updateUser(cleanSender, user);
      return sock.sendMessage(from, { text: `🛒 Gajet ${item.name} berjaya dibeli!` });
    }

    if (cmd === "jenayah_menu") {
      let c = `╭━━━ 🚨 *MISI UNDERWORLD* ━━━\n`;
      CRIMES.forEach(cr => { c += `• *[ID ${cr.id}]* ${cr.name} (Loot: RM ${cr.rewardMin}-${cr.rewardMax})\n`; });
      return sock.sendMessage(from, { text: c + `\nTaip \`.buat_jenayah [id]\`` });
    }

    if (cmd === "buat_jenayah") {
      const cr = CRIMES.find(c => c.id.toString() === args[0]);
      if (!cr) return sock.sendMessage(from, { text: `❌ Misi tidak wujud.` });
      if (cr.reqItem && !user.inventory.some(i => i.id === cr.reqItem)) {
        return sock.sendMessage(from, { text: `❌ Perlukan gajet *[${cr.reqItem}]* dari Black Market!` });
      }
      user.cooldowns.crime = now + (3 * 60 * 1000);
      if (Math.random() < 0.5) {
        const reward = Math.floor(Math.random() * (cr.rewardMax - cr.rewardMin + 1)) + cr.rewardMin;
        user.cash += reward; user.stats.crimes += 1; user.stars = Math.min(5, user.stars + 1);
        await checkAndAwardBadges(user, sock, from, cleanSender);
        updateUser(cleanSender, user);
        return sock.sendMessage(from, { text: `🦹 Berjaya! Loot +RM ${reward.toLocaleString()}`, mentions: [cleanSender] });
      } else {
        user.cash = Math.max(0, user.cash - cr.fine);
        user.cooldowns.jailUntil = now + (3 * 60 * 1000);
        updateUser(cleanSender, user);
        return sock.sendMessage(from, { text: `🚨 Kantoikan polis! Denda RM ${cr.fine} & masuk lokap 3 minit.` });
      }
    }

    if (cmd === "upah_lawyer") {
      if (user.cash < 500) return sock.sendMessage(from, { text: `❌ Perlukan RM 500 untuk upah peguam.` });
      user.cash -= 500; user.cooldowns.jailUntil = 0; user.stars = Math.max(0, user.stars - 1);
      updateUser(cleanSender, user);
      return sock.sendMessage(from, { text: `⚖️ Anda dibebaskan dari lokap oleh peguam pro!`, mentions: [cleanSender] });
    }

    if (cmd === "tanya_mamak" || cmd === "mamak") {
      const tip = DIALOG_MAMAK[Math.floor(Math.random() * DIALOG_MAMAK.length)];
      return sock.sendMessage(from, { text: `👨‍🍳 *Mamak Intel:* "${tip}"` });
    }

    if (cmd === "top" || cmd === "leaderboard") {
      const db = loadDB();
      const top = Object.entries(db.users || {}).map(([id, d]) => ({ id, total: (d.cash || 0) + (d.bank || 0) })).sort((a,b) => b.total - a.total).slice(0, 5);
      let t = `╭━━━ 🏆 *LEADERBOARD* ━━━\n`;
      top.forEach((u, i) => { t += `${i+1}. @${u.id.split("@")[0]} - RM ${u.total.toLocaleString()}\n`; });
      return sock.sendMessage(from, { text: t + `╰━━━━━━━━━━━━━━━━━━`, mentions: top.map(u => u.id) });
    }

  });
}

startBotEngine();
