JavaScript
import makeWASocket, { useMultiFileAuthState, DisconnectReason, Browsers } from "@whiskeysockets/baileys";
import pino from "pino";
import fs from "fs";
import http from "http";
import QRCode from "qrcode";
import { createCanvas } from "canvas";
import dotenv from "dotenv";
dotenv.config();

let currentQR = "";
let isConnected = false;

// --- 1. PELAYAN WEB UNTUK DISPLAY QR DI RENDER ---
const PORT = process.env.PORT || 3000;
http.createServer(async (req, res) => {
  res.writeHead(200, { "Content-Type": "text/html" });
  if (isConnected) {
    res.end("<div style='text-align:center;margin-top:50px;font-family:sans-serif;'><h1 style='color:#00e676;'>✅ AIRI'S CORNER BOT ONLINE!</h1><p>Sistem aktif 24/7 menerima arahan.</p></div>");
  } else if (currentQR) {
    try {
      const qrImage = await QRCode.toDataURL(currentQR);
      res.end(`
        <div style="text-align:center;margin-top:30px;font-family:sans-serif;background:#0d1117;color:#fff;padding:20px;min-height:90vh;">
          <h1 style="color:#00ffff;">⚡ AIRI'S CORNER : SCAN QR ⚡</h1>
          <p style="color:#aaa;">Buka WhatsApp > Linked Devices > Imbas Kod QR di bawah:</p>
          <div style="margin:20px auto;display:inline-block;padding:15px;background:#fff;border-radius:12px;">
            <img src="${qrImage}" style="width:280px;height:280px;display:block;"/>
          </div>
        </div>
      `);
    } catch (e) {
      res.end("Ralat QR: " + e.message);
    }
  } else {
    res.end("<div style='text-align:center;margin-top:50px;font-family:sans-serif;'><h2>⚡ Menjana Kod QR... Sila refresh sebentar.</h2></div>");
  }
}).listen(PORT);

// --- 2. SISTEM DATABASE JSON ---
const DB_FILE = "./database.json";
function loadDB() {
  if (!fs.existsSync(DB_FILE)) {
    fs.writeFileSync(DB_FILE, JSON.stringify({ users: {}, groups: [] }, null, 2));
  }
  try {
    return JSON.parse(fs.readFileSync(DB_FILE));
  } catch (e) {
    return { users: {}, groups: [] };
  }
}
function saveDB(data) { fs.writeFileSync(DB_FILE, JSON.stringify(data, null, 2)); }

function getUser(userId, pushName = "Warga Cyber") {
  const db = loadDB();
  if (!db.users[userId]) {
    db.users[userId] = {
      name: pushName || "Warga Cyber",
      cash: 500,
      bank: 0,
      jobId: 1,
      inventory: [],
      vehicles: [],
      food: [],
      stars: 0,
      badges: ["🌱 Warga Baru"],
      stats: { works: 0, crimes: 0, bails: 0, racesWon: 0 },
      cooldowns: { workJobs: {}, crime: 0, jailUntil: 0, daily: 0, race: 0 }
    };
    saveDB(db);
  }
  const u = db.users[userId];
  if (pushName && pushName !== "Warga Cyber") u.name = pushName;
  if (!u.stats) u.stats = { works: 0, crimes: 0, bails: 0, racesWon: 0 };
  if (!u.badges) u.badges = ["🌱 Warga Baru"];
  if (!u.food) u.food = [];
  if (!u.vehicles) u.vehicles = [];
  if (!u.inventory) u.inventory = [];
  if (!u.jobId) u.jobId = 1;
  if (!u.cooldowns) u.cooldowns = { workJobs: {}, crime: 0, jailUntil: 0, daily: 0, race: 0 };
  if (!u.cooldowns.workJobs) u.cooldowns.workJobs = {};
  return u;
}

function updateUser(userId, userData) {
  const db = loadDB();
  db.users[userId] = userData;
  saveDB(db);
}

// --- 3. GENERATOR BADGE (CANVAS DIPERBAIKI: TIDAK HITAM KOSONG) ---
async function generateBadge(badgeName, userName) {
  const width = 650;
  const height = 350;
  const canvas = createCanvas(width, height);
  const ctx = canvas.getContext("2d");

  // Background Slate Cyber
  ctx.fillStyle = "#161b22";
  ctx.fillRect(0, 0, width, height);

  // Bingkai Dalam
  ctx.fillStyle = "#0d1117";
  ctx.fillRect(15, 15, width - 30, height - 30);

  // Border Garisan Neon
  ctx.strokeStyle = "#00ffff";
  ctx.lineWidth = 4;
  ctx.strokeRect(15, 15, width - 30, height - 30);

  // Header Airi's Corner
  ctx.fillStyle = "#00ffff";
  ctx.font = "bold 26px sans-serif";
  ctx.textAlign = "center";
  ctx.fillText("⚡ AIRI'S CORNER OFFICIAL BADGE ⚡", width / 2, 65);

  // Garis Pemisah
  ctx.strokeStyle = "#ff007f";
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(50, 85);
  ctx.lineTo(600, 85);
  ctx.stroke();

  // Nama Badge (Emas Kuning Terang)
  ctx.fillStyle = "#ffd700";
  ctx.font = "bold 34px sans-serif";
  ctx.fillText(badgeName.toUpperCase(), width / 2, 155);

  // Penerima Anugerah (Nama WhatsApp)
  ctx.fillStyle = "#8b949e";
  ctx.font = "18px sans-serif";
  ctx.fillText("DIANUGERAHKAN KEPADA:", width / 2, 210);

  ctx.fillStyle = "#00e676";
  ctx.font = "bold 26px sans-serif";
  ctx.fillText(userName, width / 2, 250);

  // Serial Pengesahan
  ctx.fillStyle = "#58a6ff";
  ctx.font = "13px monospace";
  ctx.fillText(`VERIFIED ID: 0x${Math.floor(Math.random() * 899999 + 100000)} • SYSTEM AUTHENTICATED`, width / 2, 305);

  return canvas.toBuffer("image/png");
}

