const STOCKS = [
  { id: "tech", name: "Airi Tech Inc", price: 150 },
  { id: "crypto", name: "Airi CyberCoin", price: 500 },
  { id: "energy", name: "Cyber Energy", price: 200 },
  { id: "bio", name: "Nano BioTech", price: 350 },
  { id: "auto", name: "Airi Auto Motors", price: 400 }
];

