const DB_FILE = "./database.json";
function loadDB() {
  if (!fs.existsSync(DB_FILE)) {
    fs.writeFileSync(DB_FILE, JSON.stringify({ users: {}, groups: [] }, null, 2));
  }
  try { return JSON.parse(fs.readFileSync(DB_FILE)); } catch (e) { return { users: {}, groups: [] }; }
}
function saveDB(data) { fs.writeFileSync(DB_FILE, JSON.stringify(data, null, 2)); }

function getUser(userId, pushName = "Warga Cyber") {
  const db = loadDB();
  if (!db.users[userId]) {
    db.users[userId] = {
      name: pushName,
      cash: 500, bank: 0, jobId: 1, phoneDevice: null, phoneName: "Public Phone Awam",
      inventory: [], vehicles: [], food: [], portfolio: {}, stars: 0,
      badges: ["🌱 [COMMON] Warga Baru"],
      stats: { works: 0, crimes: 0, bails: 0, racesWon: 0 },
      cooldowns: { workJobs: {}, crime: 0, jailUntil: 0, daily: 0, race: 0 }
    };
    saveDB(db);
  }
  const u = db.users[userId];
  if (!u.portfolio) u.portfolio = {};
  return u;
}
function updateUser(userId, userData) { const db = loadDB(); db.users[userId] = userData; saveDB(db); }

